// ---- Configuration: the only place you edit storage details ----
// BUCKET: the S3 bucket name. "Archive Landing Page Capture" reads it from here.
// S3_BASE: the base URL the bucket is served from (S3 endpoint, CloudFront, Cloudflare...).
const BUCKET = 'your-swipe-file-bucket';
const S3_BASE = 'https://your-swipe-file-bucket.s3.eu-west-1.amazonaws.com';
const KEY_PREFIX = 'ad-landing-pages';

const d = $input.item.json; // the Analyze response
const body = $('When a Landing Page Is Submitted').item.json.body || {};

const list = (v) => (Array.isArray(v) ? v.filter(Boolean) : []);

// The H1 is the single most valuable field in a swipe file: it is the promise the
// competitor is paying for clicks on. H2s are the supporting benefits/objections.
const h1 = list(d.headings && d.headings.h1);
const h2 = list(d.headings && d.headings.h2);
const meta = d.metadata || {};
const quality = d.quality || {};

const pageUrl = d.url || body.url || '';
const slug =
  pageUrl
    .replace(/^https?:\/\//, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()
    .slice(0, 80) || 'landing-page';

// Analyze returns the capture as a hosted file URL under screenshot.link.
const screenshotLink = (d.screenshot && d.screenshot.link) || '';
const ext =
  ((screenshotLink.split('?')[0].split('.').pop() || 'png')
    .replace(/[^a-zA-Z0-9]/g, '')
    .toLowerCase()) || 'png';

const now = new Date();
const date = now.toISOString().slice(0, 10);
const objectKey = `${KEY_PREFIX}/${date}/${slug}.${ext}`;

return {
  json: {
    url: pageUrl,
    source: body.source || 'not given',
    notes: body.notes || '',
    headline: h1.join(' | ') || 'No H1 found',
    subheads: h2.join(' | ') || 'No H2 found',
    title: meta.title || '',
    description: meta.description || '',
    summary: d.summary || 'No summary generated',
    topics: list(d.topics).join(', '),
    readabilityScore: quality.readabilityScore ?? '',
    httpStatus: quality.httpStatus ?? '',
    screenshotLink,
    bucket: BUCKET,
    s3Key: objectKey,
    archiveUrl: `${S3_BASE.replace(/\/$/, '')}/${objectKey}`,
    capturedAt: now.toISOString(),
  },
};
